"""PlatformIO pre-build script: turns the picture hacks "grab" into a header,
generated/grab_image.h in the build directory, that main.cpp hands to the shim
(xshim_set_grab_image). DecayScreen melts it; upstream grabs the screen.

The picture is firmware/assets/grab-image.png (a Windows 95 screenshot), or the
file named by XS_GRAB_IMAGE (relative paths are taken from the repository
root). It is scaled to fit 466 pixels (a 640 by 480 screenshot becomes 466 by
350, about 340 KB of flash). With XS_GRAB_IMAGE=none nothing is generated and
a hack that wants a picture loads nothing. Needs uv, because Pillow is not in
PlatformIO's Python."""

import os
import shutil
import subprocess
import sys
from pathlib import Path

Import("env")  # noqa: F821

project = Path(env["PROJECT_DIR"])  # noqa: F821
header = Path(env.subst("$BUILD_DIR")) / "generated" / "grab_image.h"  # noqa: F821
GRAB_SIZE = 466

choice = os.environ.get("XS_GRAB_IMAGE", "")
image = None
if choice != "none":
    image = Path(choice) if choice else project / "assets" / "grab-image.png"
    if not image.is_absolute():
        image = project.parent / image
    if not image.is_file():
        sys.exit(f"XS_GRAB_IMAGE={choice or 'default'}: no such file ({image})")

if image is None:
    header.unlink(missing_ok=True)
else:
    uv = shutil.which("uv")
    if not uv:
        raise SystemExit("the grab image needs uv on PATH to convert the image")
    subprocess.run(
        [
            uv,
            "run",
            str(project.parent / "tools" / "make_logo_blob.py"),
            str(image),
            "--name",
            "grab_image_blob",
            "--size",
            str(GRAB_SIZE),
            "-o",
            str(header),
        ],
        check=True,
    )
    print(f"Grab image: {image}")
      }
  free(i1->data); i1->data = 0;
  XDestroyImage(i1);
  XPutImage(dpy, p2, gc, i2, 0, 0, 0, 0, i2->width, i2->height);
  XFreeGC (dpy, gc);
  free(i2->data); i2->data = 0;
  XDestroyImage(i2);
  XFreePixmap(dpy, pixmap);
  return p2;
}


static void
load_images_1 (Display *dpy, m_state *state, int which)
{
  const unsigned char *png = 0;
  unsigned long size = 0;
  if (which == 1)
    {
      if (state->small_p)
        png = matrix1b_png, size = sizeof(matrix1b_png);
      else
        png = matrix1_png, size = sizeof(matrix1_png);
    }
  else
    {
      if (state->small_p)
        png = matrix2b_png, size = sizeof(matrix2b_png);
      else
        png = matrix2_png, size = sizeof(matrix2_png);
    }
  state->images[which] =
    image_data_to_pixmap (state->dpy, state->window, png, size,
                          &state->image_width, &state->image_height, 0);

  if (state->xgwa.width > 1920 || state->xgwa.height > 1920)
    { /* Retina displays */
      state->images[which] =
        double_pixmap (state->dpy, state->xgwa.visual,
                       state->xgwa.depth, state->images[which],
                       state->image_width, state->image_height);
      state->image_width *= 2;
      state->image_height *= 2;
    }
}


static void
load_images (Display *dpy, m_state *state)
{
  load_images_1 (dpy, state, 1);
  load_images_1 (dpy, state, 2);
}


static void
flip_images_1 (m_state *state, int which)
{
  XImage *im = XGetImage (state->dpy, state->images[which], 0, 0,
                          state->image_width, state->image_height,
                          ~0L, (state->xgwa.depth > 1 ? ZPixmap : XYPixmap));
  state->dpy = dpy;
  state->window = window;
  state->delay = get_integer_resource (dpy, "delay", "Integer");

  XGetWindowAttributes (dpy, window, &state->xgwa);

  state->small_p = (state->xgwa.width < 300);
  {
    char *s = get_string_resource (dpy, "matrixFont", "String");
    if (!s || !*s || !strcasecmp(s, "large"))
      state->small_p = False;
    else if (!strcasecmp(s, "small"))
      state->small_p = True;
    else
      fprintf (stderr, "%s: matrixFont should be 'small' or 'large' not '%s'\n",
               progname, s);
    if (s) free (s);
  }

  load_images (dpy, state);

  gcv.foreground = get_pixel_resource(state->dpy, state->xgwa.colormap,
                                      "foreground", "Foreground");
  gcv.background = get_pixel_resource(state->dpy, state->xgwa.colormap,
                                      "background", "Background");
  state->draw_gc = XCreateGC (state->dpy, state->window,
                              GCForeground|GCBackground, &gcv);
  gcv.foreground = gcv.background;
  state->erase_gc = XCreateGC (state->dpy, state->window,
                               GCForeground|GCBackground, &gcv);

