  const unsigned long n_long = deflate_blob(longer, sizeof(longer), body + 1);
  const unsigned long n_corrupt = deflate_blob(corrupt, sizeof(corrupt), body);
  corrupt[n_corrupt / 2] ^= 0xFF;
  struct {
    const unsigned char *data;
    unsigned long size;
