/* Past INT16_MAX a side is more than the canvas allows, and on the device a
 * 65535 by 65535 blob's size would wrap the 32-bit size_t passed to malloc. */
void test_a_blob_wider_or_taller_than_int16_max_is_rejected(void) {
  enum { SIDE = 32768 };
  const unsigned long body_len = 2 * SIDE + SIDE / 8;
  unsigned char *body = (unsigned char *)calloc(1, body_len);
  uLongf packed_len = compressBound(body_len);
  unsigned char *wide = (unsigned char *)malloc(8 + packed_len);
  unsigned char *tall = (unsigned char *)malloc(8 + packed_len);
  TEST_ASSERT_EQUAL_INT(Z_OK, compress2(wide + 8, &packed_len, body, body_len, 9));
  memcpy(wide, "565Z", 4);
  wide[4] = SIDE & 0xFF, wide[5] = SIDE >> 8, wide[6] = 1, wide[7] = 0;
  /* A 1 wide column's mask has a byte a row: a different body size. */
  uLongf tall_len = compressBound(3 * SIDE);
  unsigned char *tall_body = (unsigned char *)calloc(1, 3 * SIDE);
  free(tall);
  tall = (unsigned char *)malloc(8 + tall_len);
  TEST_ASSERT_EQUAL_INT(Z_OK, compress2(tall + 8, &tall_len, tall_body, 3 * SIDE, 9));
  memcpy(tall, "565Z", 4);
  tall[4] = 1, tall[5] = 0, tall[6] = SIDE & 0xFF, tall[7] = SIDE >> 8;

  TEST_ASSERT_NULL(image_data_to_ximage(dpy, NULL, wide, 8 + packed_len));
  TEST_ASSERT_NULL(image_data_to_ximage(dpy, NULL, tall, 8 + tall_len));
  /* One pixel less on each is still accepted. */
  wide[4] = (SIDE - 1) & 0xFF, wide[5] = (SIDE - 1) >> 8;
  packed_len = compressBound(body_len);
  const unsigned long ok_len = 2 * (SIDE - 1) + (SIDE - 1 + 7) / 8;
  TEST_ASSERT_EQUAL_INT(Z_OK, compress2(wide + 8, &packed_len, body, ok_len, 9));
  XImage *im = image_data_to_ximage(dpy, NULL, wide, 8 + packed_len);
  TEST_ASSERT_NOT_NULL(im);
  XDestroyImage(im);
  free(body);
  free(tall_body);
  free(wide);
  free(tall);
}

